    """Set of every tracked integer point; O(right - left) per operation."""

    def __init__(self):
        self.points = set()

    def addRange(self, left: int, right: int) -> None:
        self.points.update(range(left, right))

    def queryRange(self, left: int, right: int) -> bool:
        return all(x in self.points for x in range(left, right))

    def removeRange(self, left: int, right: int) -> None:
        self.points.difference_update(range(left, right))

class BruteForce:
    """Set of seen values; getIntervals re-sorts and re-merges everything, O(n log n)."""

    def __init__(self):
        self.seen = set()

    def addNum(self, value: int) -> None:
        self.seen.add(value)

    def getIntervals(self) -> List[List[int]]:
        out = []
        for v in sorted(self.seen):
            if out and out[-1][1] == v - 1:
                out[-1][1] = v
            else:
                out.append([v, v])
        return out

