class Solution:
    def minPatches(self, nums: List[int], n: int) -> int:
        reach = 0            # invariant: every sum in [1, reach] is buildable
        patches = i = 0
        while reach < n:
            if i < len(nums) and nums[i] <= reach + 1:
                reach += nums[i]           # no hole: [1, reach] + x covers [1, reach + x]
                i += 1
            else:
                reach += reach + 1         # patch with reach + 1: coverage doubles
                patches += 1
        return patches

class Solution:
    def splitArray(self, nums: List[int], k: int) -> int:
        def pieces_needed(cap: int) -> int:
            """Greedy: fewest pieces with every piece sum <= cap."""
            count, cur = 1, 0
            for x in nums:
                if cur + x > cap:          # would spill over: start a new piece
                    count += 1
                    cur = 0
                cur += x
            return count

        lo, hi = max(nums), sum(nums)      # feasible answers live in [lo, hi]
        while lo < hi:
            mid = (lo + hi) // 2
            if pieces_needed(mid) <= k:    # mid works -> try smaller
                hi = mid
            else:
                lo = mid + 1
        return lo

