def brute_force(n: int, ranges: List[int]) -> int:
    """Try every subset of taps by increasing size (exponential), check coverage of [0, n]."""
    taps = list(range(n + 1))
    for size in range(0, n + 2):
        for chosen in combinations(taps, size):
            wet = [False] * n                       # wet[p] = unit segment [p, p+1] watered
            for i in chosen:
                for p in range(max(0, i - ranges[i]), min(n, i + ranges[i])):
                    wet[p] = True
            if all(wet):
                return size
    return -1

def brute_force(intervals: List[List[int]]) -> int:
    """Try every subset of candidate points by increasing size (exponential)."""
    lo = min(s for s, _ in intervals)
    hi = max(e for _, e in intervals)
    points = range(lo, hi + 1)
    for size in range(2, len(points) + 1):
        for chosen in combinations(points, size):
            if all(sum(s <= p <= e for p in chosen) >= 2 for s, e in intervals):
                return size
    return -1   # unreachable: every interval has length >= 1 so all points always work

def brute_force(row: List[int]) -> int:
    """BFS over seatings, one swap per edge; exponential state space (2n)!."""
    def solved(state: tuple) -> bool:
        return all(state[i] // 2 == state[i + 1] // 2 for i in range(0, len(state), 2))

    start = tuple(row)
    dist = {start: 0}
    queue = deque([start])
    while queue:
        cur = queue.popleft()
        if solved(cur):
            return dist[cur]
        for i in range(len(cur)):
            for j in range(i + 1, len(cur)):
                nxt = list(cur)
                nxt[i], nxt[j] = nxt[j], nxt[i]
                nxt = tuple(nxt)
                if nxt not in dist:
                    dist[nxt] = dist[cur] + 1
                    queue.append(nxt)
    return -1

