def brute_force(stamp: str, target: str) -> List[int]:
    """Forward BFS over partial strings from '???...'; exponential state space."""
    m, n = len(stamp), len(target)
    start = "?" * n
    prev = {start: None}
    queue = deque([start])
    while queue:
        cur = queue.popleft()
        if cur == target:
            path = []
            while prev[cur] is not None:
                cur, pos = prev[cur]
                path.append(pos)
            return path[::-1]
        for i in range(n - m + 1):
            nxt = cur[:i] + stamp + cur[i + m:]
            if nxt not in prev:
                prev[nxt] = (cur, i)
                queue.append(nxt)
    return []

